WITH probe(x) AS (VALUES (31976016),(31976025),(31976055),(31976056),(31976066),(31976088),(31976094),(31976116),(31976127),(31976142),(31976159),(31976162),(31976177),(31976178),(31976186),(31976191),(31976193),(31976203),(31976229),(31976233),(31976235),(31976243),(31976256),(31976280),(31976299),(31976301),(31976302),(31976321),(31976324),(31976334),(31976335),(31976339),(31976356),(31976371),(31976372),(31976393),(31976399),(31976426),(31976499),(31976503),(31976509),(31976555),(31976619),(31976627),(31976634),(31976638),(31976653),(31976654),(31976677),(31976682),(31976723),(31976727),(31976731),(31976733),(31976737),(31976878),(31976879),(31976884),(31976908),(31976911),(31976925),(31976931),(31976934),(31976937),(31976958),(31976989),(31977003),(31977006),(31977007),(31977011),(31977027),(31977029),(31977034),(31977044),(31977048),(31977061),(31977122),(31977139),(31977178),(31977183),(31977190),(31977191),(31977199),(31977213),(31977246),(31977270),(31977289),(31977292),(31977311),(31977328),(31977332),(31977337),(31977351),(31977354),(31977363),(31977371),(31977374),(31977404),(31977418),(31977426),(31977441),(31977442),(31977443),(31977444),(31977445),(31977448),(31977449),(31977450),(31977458),(31977462),(31977484),(31977495),(31977501),(31977502),(31977542),(31977548),(31977555),(31977593),(31977595),(31977596),(31977608),(31977668),(31977674),(31977687),(31977717),(31977724),(31977743),(31977755),(31977785),(31977795),(31977799),(31977810),(31977830),(31977887),(31977909),(31977956),(31977958),(31977966),(31977980),(31978006),(31978007),(31978036),(31978039),(31978046),(31978060),(31978061),(31978067),(31978081),(31978090),(31978099),(31978113),(31978126),(31978138),(31978173),(31978174),(31978188),(31978190),(31978194),(31978201),(31978227),(31978235),(31978236),(31978238),(31978249),(31978265),(31978267),(31978334),(31978338),(31978367),(31978375),(31978376),(31978388),(31978391),(31978406),(31978432),(31978465),(31978490),(31978491),(31978515),(31978542),(31978595),(31978597),(31978602),(31978618),(31978621),(31978632),(31978690),(31978708),(31978719),(31978720))
SELECT p.x AS org, b.organization_id AS parent_org, count(*) AS n, count(DISTINCT m.notice_id) AS notices,
 min(b.name) AS parent_name_min, max(b.name) AS parent_name_max,
 (SELECT po.identifier IS NOT NULL FROM organizations po WHERE po.id = b.organization_id) AS parent_identified,
 min((SELECT min(t.value) FROM notice_texts t WHERE t.notice_id = m.notice_id AND t.section_id = m.section_id AND t.field_id = 'BT-513-Organization-TouchPoint')) AS city_min,
 max((SELECT max(t.value) FROM notice_texts t WHERE t.notice_id = m.notice_id AND t.section_id = m.section_id AND t.field_id = 'BT-513-Organization-TouchPoint')) AS city_max
FROM probe p
CROSS JOIN organization_mentions m ON m.organization_id = p.x
CROSS JOIN notice_sections s ON s.notice_id = m.notice_id AND s.section_id = m.section_id
LEFT JOIN organization_mentions b ON b.notice_id = s.notice_id AND b.section_id = s.parent_section_id
GROUP BY +p.x, +b.organization_id
